import time, os, hashlib
from cryptography.hazmat.primitives import hashes

data = os.urandom(20000 * 1024)
print("data size", len(data))

def bench(fn, n=5):
    # warmup
    fn()
    t0 = time.perf_counter()
    for _ in range(n):
        fn()
    t1 = time.perf_counter()
    return (t1-t0)/n

def crypto():
    d = hashes.Hash(hashes.SHA256())
    d.update(data)
    return d.finalize()

def hlib():
    return hashlib.sha256(data).digest()

def hlib2():
    h = hashlib.sha256()
    h.update(data)
    return h.digest()

print("crypto", bench(crypto))
print("hashlib", bench(hlib))
print("hashlib2", bench(hlib2))
print("equal", crypto()==hlib())
EOF"}

