/* AVX2 SHA-256, 2-way interleaved (two independent 64-byte blocks processed
   with 256-bit SIMD by packing two 32-bit lanes... actually for a SINGLE
   message the classic approach is 4-way message schedule + scalar state,
   or fully scalar optimized. Let's first do a tight scalar version and an
   AVX2 message-schedule version for a single stream, which is what OpenSSL
   does and gets ~180MB/s. If we match that, overhead is elsewhere.

   Also implement 4 independent streams? No, we have one message.

   Plan: highly optimized scalar SHA-256 with careful scheduling, compiled -O3 -march=native.
*/
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <immintrin.h>

