static inline uint32_t rotr(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }
static inline uint32_t bswap32(uint32_t x){
    return __builtin_bswap32(x);
}

#define RND(a,b,c,d,e,f,g,h,k,w) do { \
    uint32_t t1 = h + (rotr(e,6)^rotr(e,11)^rotr(e,25)) + ((e&f)^((~e)&g)) + k + w; \
    uint32_t t2 = (rotr(a,2)^rotr(a,13)^rotr(a,22)) + ((a&b)^(a&c)^(b&c)); \
    h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2; \
} while(0)

static void sha256_scalar(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t H[8] = {
        0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
        0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
    };
    uint8_t block[64];
    size_t off = 0;
    uint64_t bitlen = (uint64_t)len * 8;

    while (off + 64 <= len) {
        const uint8_t *p = data + off;
        uint32_t w[64];
        for (int i=0;i<16;i++) {
            w[i] = ((uint32_t)p[i*4]<<24)|((uint32_t)p[i*4+1]<<16)|((uint32_t)p[i*4+2]<<8)|p[i*4+3];
        }
        for (int i=16;i<64;i++) {
            uint32_t s0 = rotr(w[i-15],7)^rotr(w[i-15],18)^(w[i-15]>>3);
            uint32_t s1 = rotr(w[i-2],17)^rotr(w[i-2],19)^(w[i-2]>>10);
            w[i] = w[i-16]+s0+w[i-7]+s1;
        }
        uint32_t a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
        for (int i=0;i<64;i++) RND(a,b,c,d,e,f,g,h,K[i],w[i]);
        H[0]+=a;H[1]+=b;H[2]+=c;H[3]+=d;H[4]+=e;H[5]+=f;H[6]+=g;H[7]+=h;
        off += 64;
    }
    /* padding */
    size_t rem = len - off;
    memset(block, 0, 64);
    memcpy(block, data+off, rem);
    block[rem] = 0x80;
    if (rem >= 56) {
        /* process this block then a zero block with length */
        uint32_t w[64];
        for (int i=0;i<16;i++)
            w[i] = ((uint32_t)block[i*4]<<24)|((uint32_t)block[i*4+1]<<16)|((uint32_t)block[i*4+2]<<8)|block[i*4+3];
        for (int i=16;i<64;i++) {
            uint32_t s0 = rotr(w[i-15],7)^rotr(w[i-15],18)^(w[i-15]>>3);
            uint32_t s1 = rotr(w[i-2],17)^rotr(w[i-2],19)^(w[i-2]>>10);
            w[i] = w[i-16]+s0+w[i-7]+s1;
        }
        uint32_t a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
        for (int i=0;i<64;i++) RND(a,b,c,d,e,f,g,h,K[i],w[i]);
        H[0]+=a;H[1]+=b;H[2]+=c;H[3]+=d;H[4]+=e;H[5]+=f;H[6]+=g;H[7]+=h;
        memset(block, 0, 64);
    }
    block[63] = (uint8_t)(bitlen);
    block[62] = (uint8_t)(bitlen>>8);
    block[61] = (uint8_t)(bitlen>>16);
    block[60] = (uint8_t)(bitlen>>24);
    block[59] = (uint8_t)(bitlen>>32);
    block[58] = (uint8_t)(bitlen>>40);
    block[57] = (uint8_t)(bitlen>>48);
    block[56] = (uint8_t)(bitlen>>56);
    {
        uint32_t w[64];
        for (int i=0;i<16;i++)
            w[i] = ((uint32_t)block[i*4]<<24)|((uint32_t)block[i*4+1]<<16)|((uint32_t)block[i*4+2]<<8)|block[i*4+3];
        for (int i=16;i<64;i++) {
            uint32_t s0 = rotr(w[i-15],7)^rotr(w[i-15],18)^(w[i-15]>>3);
            uint32_t s1 = rotr(w[i-2],17)^rotr(w[i-2],19)^(w[i-2]>>10);
            w[i] = w[i-16]+s0+w[i-7]+s1;
        }
        uint32_t a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
        for (int i=0;i<64;i++) RND(a,b,c,d,e,f,g,h,K[i],w[i]);
        H[0]+=a;H[1]+=b;H[2]+=c;H[3]+=d;H[4]+=e;H[5]+=f;H[6]+=g;H[7]+=h;
    }
    for (int i=0;i<8;i++) {
        out[i*4] = (uint8_t)(H[i]>>24);
        out[i*4+1] = (uint8_t)(H[i]>>16);
        out[i*4+2] = (uint8_t)(H[i]>>8);
        out[i*4+3] = (uint8_t)(H[i]);
    }
}

/* AVX2: process message schedule with SIMD, state scalar. This is the
   standard single-stream AVX2 approach used by many libs. */
static void sha256_avx2(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t H0=0x6a09e667,H1=0xbb67ae85,H2=0x3c6ef372,H3=0xa54ff53a;
    uint32_t H4=0x510e527f,H5=0x9b05688c,H6=0x1f83d9ab,H7=0x5be0cd19;

    const __m128i shuf = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    const __m128i s0_mask = _mm_set1_epi32(0); /* unused */

    size_t nblocks = len / 64;
    const uint8_t *p = data;

    for (size_t blk=0; blk<nblocks; blk++, p+=64) {
        __m128i W[16];
        /* load 16 words, byte-swap */
        for (int i=0;i<4;i++) {
            __m128i v = _mm_loadu_si128((const __m128i*)(p+i*16));
            W[i] = _mm_shuffle_epi8(v, shuf);
        }
        /* expand W[4..15] using SSE */
        for (int i=4;i<16;i++) {
            /* s0 = rotr7 ^ rotr18 ^ shr3 of w[i-15] which is lane of W[i-4] shifted */
            /* This lane-wise expansion across 128-bit chunks is awkward.
               Fall back: extract to scalar array. The win of AVX2 single-stream
               over a good scalar compiler is modest. We'll measure scalar first.
            */
        }
        uint32_t w[64];
        _mm_storeu_si128((__m128i*)w, W[0]);
        _mm_storeu_si128((__m128i*)(w+4), W[1]);
        _mm_storeu_si128((__m128i*)(w+8), W[2]);
        _mm_storeu_si128((__m128i*)(w+12), W[3]);
        for (int i=16;i<64;i++) {
            uint32_t x = w[i-15];
            uint32_t y = w[i-2];
            uint32_t s0 = rotr(x,7)^rotr(x,18)^(x>>3);
            uint32_t s1 = rotr(y,17)^rotr(y,19)^(y>>10);
            w[i] = w[i-16]+s0+w[i-7]+s1;
        }
        uint32_t a=H0,b=H1,c=H2,d=H3,e=H4,f=H5,g=H6,h=H7;
        for (int i=0;i<64;i++) RND(a,b,c,d,e,f,g,h,K[i],w[i]);
        H0+=a;H1+=b;H2+=c;H3+=d;H4+=e;H5+=f;H6+=g;H7+=h;
    }
    /* tail + padding via scalar function on remaining by reconstructing is messy.
       For benchmark of bulk, if len%64==0 we still need padding block. */
    size_t rem = len % 64;
    uint8_t tail[128];
    memset(tail, 0, sizeof(tail));
    if (rem) memcpy(tail, p, rem);
    tail[rem] = 0x80;
    uint64_t bitlen = (uint64_t)len * 8;
    size_t padblocks = (rem >= 56) ? 2 : 1;
    uint8_t *lp = tail + padblocks*64 - 8;
    for (int i=7;i>=0;i--) { lp[i] = (uint8_t)bitlen; bitlen >>= 8; }
    /* process pad blocks with the same scalar rounds by calling sha256_scalar logic inline */
    p = tail;
    for (size_t blk=0; blk<padblocks; blk++, p+=64) {
        uint32_t w[64];
        for (int i=0;i<16;i++)
            w[i] = ((uint32_t)p[i*4]<<24)|((uint32_t)p[i*4+1]<<16)|((uint32_t)p[i*4+2]<<8)|p[i*4+3];
        for (int i=16;i<64;i++) {
            uint32_t s0 = rotr(w[i-15],7)^rotr(w[i-15],18)^(w[i-15]>>3);
            uint32_t s1 = rotr(w[i-2],17)^rotr(w[i-2],19)^(w[i-2]>>10);
            w[i] = w[i-16]+s0+w[i-7]+s1;
        }
        uint32_t a=H0,b=H1,c=H2,d=H3,e=H4,f=H5,g=H6,h=H7;
        for (int i=0;i<64;i++) RND(a,b,c,d,e,f,g,h,K[i],w[i]);
        H0+=a;H1+=b;H2+=c;H3+=d;H4+=e;H5+=f;H6+=g;H7+=h;
    }
    uint32_t Hs[8] = {H0,H1,H2,H3,H4,H5,H6,H7};
    for (int i=0;i<8;i++) {
        out[i*4]=(uint8_t)(Hs[i]>>24); out[i*4+1]=(uint8_t)(Hs[i]>>16);
        out[i*4+2]=(uint8_t)(Hs[i]>>8); out[i*4+3]=(uint8_t)Hs[i];
    }
}

#include <openssl/sha.h>
int main() {
    size_t len = 20000 * 1024;
    uint8_t *data = malloc(len);
    for (size_t i=0;i<len;i++) data[i] = (uint8_t)(i*131u + 17u);
    uint8_t out1[32], out2[32], out3[32];

    /* warmup */
    sha256_scalar(data, len, out1);
    SHA256(data, len, out3);
    printf("match scalar %d\n", memcmp(out1,out3,32)==0);
    sha256_avx2(data, len, out2);
    printf("match avx2 %d\n", memcmp(out2,out3,32)==0);

    int N = 5;
    clock_t t0 = clock();
    for (int i=0;i<N;i++) sha256_scalar(data, len, out1);
    clock_t t1 = clock();
    for (int i=0;i<N;i++) SHA256(data, len, out3);
    clock_t t2 = clock();
    for (int i=0;i<N;i++) sha256_avx2(data, len, out2);
