    printf("openssl %.1f MB/s\n", mb / ((t2-t1)/(double)CLOCKS_PER_SEC));
    printf("avx2mix %.1f MB/s\n", mb / ((t3-t2)/(double)CLOCKS_PER_SEC));
    free(data);
    return 0;
}
