#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <openssl/sha.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

typedef struct {
    const uint8_t *data;
    size_t len;
    uint8_t out[32];
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    SHA256(j->data, j->len, j->out);
    return NULL;
}

/* Parallel tree: split into N chunks, hash each, then hash the concatenation of digests.
   NOT standard SHA-256. Just measuring reduction overhead. */
static void tree(const uint8_t *data, size_t len, int nthreads, uint8_t out[32]) {
    pthread_t th[16];
    job_t jobs[16];
    size_t chunk = (len / nthreads) & ~63ull; /* align */
    if (chunk == 0) chunk = len;
    size_t off = 0;
    int actual = 0;
    for (int i=0;i<nthreads;i++) {
        size_t n = (i==nthreads-1) ? (len-off) : chunk;
        if (off>=len) break;
        jobs[i].data = data+off;
        jobs[i].len = n;
        off += n;
        pthread_create(&th[i], NULL, worker, &jobs[i]);
        actual++;
    }
    for (int i=0;i<actual;i++) pthread_join(th[i], NULL);
    uint8_t cat[16*32];
    for (int i=0;i<actual;i++) memcpy(cat+i*32, jobs[i].out, 32);
    SHA256(cat, actual*32, out);
}

int main() {
    size_t len = 20000u*1024u;
    uint8_t *data = malloc(len);
    memset(data, 0xab, len);
    uint8_t out[32];
    int N=4;
    for (int th=1; th<=8; th++) {
        tree(data, len, th, out); /* warmup */
        double t0=now();
        for (int i=0;i<N;i++) tree(data, len, th, out);
        double t1=now();
        printf("threads %d  %.4f s/hash  %.1f MB/s\n", th, (t1-t0)/N, (len*(double)N/1e6)/(t1-t0));
    }
    free(data);
    return 0;
}
