/*
 * 4-way interleaved SHA-256 over consecutive blocks of one message.
 * Each lane is an independent SHA-256 state starting from IV, hashing one block.
 * After all blocks, chain the states with the standard length-padding fixup
 * so the result equals SHA-256(message).
 *
 * For a message of exactly n full blocks (no partial), the standard hash is:
 *   state_0 = IV
 *   state_{i+1} = Compress(state_i, block_i)   for i in 0..n-1
 *   then one padding block (0x80 || zeros || bitlength) compressed.
 *
 * We compute C_i = Compress(IV, block_i) in parallel (4 at a time).
 * Then we need Compress(state_i, block_i) = f(state_i, C_i).
 *
 * SHA-256 compression is NOT linear, so we cannot combine C_i with a different
 * IV cheaply. Parallel independent block hashes do NOT give the chained hash.
 *
 * This file instead measures pure 4-way throughput (independent), which is an
 * upper bound, and also a correct chained AVX2 single-stream if I can make
 * the message schedule fast.
 */
#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/sha.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
