    cycles = (double)(t1-t0);
    printf("SHA256():         %.2f cycles/byte\n", cycles/bytes);

    /* frequency estimate: rdtsc vs wall */
    struct timespec ts0, ts1;
    clock_gettime(CLOCK_MONOTONIC, &ts0);
    t0 = rdtsc();
    /* burn */
    volatile uint64_t x = 0;
    for (int i=0;i<200000000;i++) x += i;
    t1 = rdtsc();
    clock_gettime(CLOCK_MONOTONIC, &ts1);
    double wall = (ts1.tv_sec-ts0.tv_sec) + (ts1.tv_nsec-ts0.tv_nsec)*1e-9;
    printf("rdtsc freq during scalar loop: %.2f GHz  (wall %.3fs)\n", (t1-t0)/wall/1e9, wall);

    clock_gettime(CLOCK_MONOTONIC, &ts0);
