/* Single-stream SHA-256 with AVX2 message schedule (SSE/AVX) and scalar rounds,
   modeled on the structure that gets ~12-15 cpb. Also an 8-lane version that
   chains by feeding previous lane state... no, chaining isn't lane-parallel.

   This version: fully unrolled scalar rounds + SIMD schedule, processing 1 block.
   Goal: beat OpenSSL's 21 cpb. If we get to 12 cpb that's only 1.7x. Not enough
   alone, but combined with threads it would be.

   Also implement 2-block software pipelining: while computing rounds of block i,
   prefetch/schedule block i+1. Limited win.
*/
#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/sha.h>

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

static const uint32_t K[64] __attribute__((aligned(64))) = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
