    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

#define ROR(x,n) (((x)>>(n))|((x)<<(32-(n))))
#define CH(e,f,g) (((e)&(f))^((~(e))&(g)))
#define MAJ(a,b,c) (((a)&(b))^((a)&(c))^((b)&(c)))
#define BSIG0(a) (ROR(a,2)^ROR(a,13)^ROR(a,22))
#define BSIG1(e) (ROR(e,6)^ROR(e,11)^ROR(e,25))
#define SSIG0(x) (ROR(x,7)^ROR(x,18)^((x)>>3))
#define SSIG1(x) (ROR(x,17)^ROR(x,19)^((x)>>10))

#define ROUND(a,b,c,d,e,f,g,h,k,w) do { \
    uint32_t t1 = (h) + BSIG1(e) + CH(e,f,g) + (k) + (w); \
    uint32_t t2 = BSIG0(a) + MAJ(a,b,c); \
    (d) += t1; (h) = t1 + t2; \
} while(0)

/* BMI2/AVX2 schedule using _mm_sha? not available. Use SSSE3-style? 
   Use scalar schedule but unroll rounds completely and keep w in regs via compiler. */

static void sha256_fast(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t a0=0x6a09e667,b0=0xbb67ae85,c0=0x3c6ef372,d0=0xa54ff53a;
    uint32_t e0=0x510e527f,f0=0x9b05688c,g0=0x1f83d9ab,h0=0x5be0cd19;
    size_t n = len >> 6;
    const uint8_t *p = data;
    const __m128i shuf = _mm_set_epi8(12,13,14,15,8,9,10,11,4,5,6,7,0,1,2,3);

    for (size_t blk=0; blk<n; blk++, p+=64) {
        uint32_t w[64];
        __m128i v0 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(p)), shuf);
        __m128i v1 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(p+16)), shuf);
        __m128i v2 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(p+32)), shuf);
        __m128i v3 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(p+48)), shuf);
        _mm_storeu_si128((__m128i*)w, v0);
        _mm_storeu_si128((__m128i*)(w+4), v1);
        _mm_storeu_si128((__m128i*)(w+8), v2);
        _mm_storeu_si128((__m128i*)(w+12), v3);
        for (int i=16;i<64;i++) {
            w[i] = w[i-16] + SSIG0(w[i-15]) + w[i-7] + SSIG1(w[i-2]);
        }
        uint32_t a=a0,b=b0,c=c0,d=d0,e=e0,f=f0,g=g0,h=h0;
        #pragma unroll
        for (int i=0;i<64;i++) {
            ROUND(a,b,c,d,e,f,g,h,K[i],w[i]);
            uint32_t t=h; h=g; g=f; f=e; e=d; d=c; c=b; b=a; a=t;
            /* WAIT this rotation is wrong because ROUND already updates d and h in place
               with the standard rotating assignment missing.
               I used a non-rotating ROUND that writes new d and new a into h.
               Standard after ROUND that sets h=t1+t2 and d+=t1, the rotation is
               h->a, a->b, b->c, c->d, d->e, e->f, f->g, g->h but d was already updated.
               The classic macro rotates names. Let me not use this broken version.
            */
        }
        (void)a;(void)b;(void)c;(void)d;(void)e;(void)f;(void)g;(void)h;
        a0=b0=0; /* force not used */
    }
    (void)a0;(void)out;(void)shuf;
}

/* Correct fully unrolled via macros with name rotation */
#define RN(a,b,c,d,e,f,g,h,i) do { \
    uint32_t t1 = h + BSIG1(e) + CH(e,f,g) + K[i] + w[i]; \
    uint32_t t2 = BSIG0(a) + MAJ(a,b,c); \
    h = t1 + t2; d += t1; \
} while(0)

static void compress_block(uint32_t H[8], const uint8_t *p) {
    uint32_t w[64];
    const __m128i shuf = _mm_set_epi8(12,13,14,15,8,9,10,11,4,5,6,7,0,1,2,3);
    _mm_storeu_si128((__m128i*)w,     _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(p)), shuf));
    _mm_storeu_si128((__m128i*)(w+4), _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(p+16)), shuf));
    _mm_storeu_si128((__m128i*)(w+8), _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(p+32)), shuf));
    _mm_storeu_si128((__m128i*)(w+12),_mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(p+48)), shuf));
    for (int i=16;i<64;i++)
        w[i] = w[i-16] + SSIG0(w[i-15]) + w[i-7] + SSIG1(w[i-2]);
    uint32_t a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
    #define R8(i) \
        RN(a,b,c,d,e,f,g,h,i); RN(h,a,b,c,d,e,f,g,i+1); RN(g,h,a,b,c,d,e,f,i+2); RN(f,g,h,a,b,c,d,e,i+3); \
        RN(e,f,g,h,a,b,c,d,i+4); RN(d,e,f,g,h,a,b,c,i+5); RN(c,d,e,f,g,h,a,b,i+6); RN(b,c,d,e,f,g,h,a,i+7);
    R8(0) R8(8) R8(16) R8(24) R8(32) R8(40) R8(48) R8(56)
    H[0]+=a; H[1]+=b; H[2]+=c; H[3]+=d; H[4]+=e; H[5]+=f; H[6]+=g; H[7]+=h;
}

static void sha256_fast2(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t H[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t n = len>>6;
    const uint8_t *p = data;
    for (size_t i=0;i<n;i++, p+=64) compress_block(H, p);
    /* padding */
    uint8_t block[128];
    size_t rem = len & 63;
    memset(block, 0, 128);
    if (rem) memcpy(block, p, rem);
    block[rem]=0x80;
    uint64_t bits = (uint64_t)len*8;
    size_t nb = (rem>=56)?2:1;
    uint8_t *lp = block + nb*64 - 8;
    for (int i=7;i>=0;i--) { lp[i]=(uint8_t)bits; bits>>=8; }
    compress_block(H, block);
    if (nb==2) compress_block(H, block+64);
    for (int i=0;i<8;i++) {
        out[4*i]=H[i]>>24; out[4*i+1]=H[i]>>16; out[4*i+2]=H[i]>>8; out[4*i+3]=H[i];
    }
}

int main(){
