    double t1=now();
    printf("fast2 %.4fs %.1f MB/s\n", (t1-t0)/N, (len*(double)N/1e6)/(t1-t0));
    t0=now();
    for(int i=0;i<N;i++) SHA256(data,len,o2);
    t1=now();
    printf("openssl %.4fs %.1f MB/s\n", (t1-t0)/N, (len*(double)N/1e6)/(t1-t0));
    free(data);
    return 0;
}
