static uint32_t try_rorx(uint32_t x) {
    uint32_t r;
    __asm__ volatile("rorx $7, %1, %0" : "=r"(r) : "r"(x));
    return r;
}
/* mulx */
static uint64_t try_mulx(uint64_t a, uint64_t b) {
    uint64_t hi, lo;
    __asm__ volatile("mulx %2, %0, %1" : "=r"(lo), "=r"(hi) : "r"(b), "d"(a));
