#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <time.h>
#include <openssl/sha.h>

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }
typedef void (*block_fn)(uint32_t *state, const void *data, size_t nblocks);

static void sha256_via(block_fn fn, const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                      0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t nblocks = len >> 6;
    size_t rem = len & 63;
    if (nblocks) fn(st, data, nblocks);
    uint8_t block[128];
    memset(block, 0, 128);
    if (rem) memcpy(block, data + (nblocks<<6), rem);
    block[rem] = 0x80;
    uint64_t bits = (uint64_t)len * 8;
    size_t nb = (rem >= 56) ? 2 : 1;
    uint8_t *lp = block + nb*64 - 8;
    for (int i=7;i>=0;i--) { lp[i] = (uint8_t)bits; bits >>= 8; }
    fn(st, block, nb);
    for (int i=0;i<8;i++) {
        out[4*i]=st[i]>>24; out[4*i+1]=st[i]>>16; out[4*i+2]=st[i]>>8; out[4*i+3]=st[i];
    }
}

int main() {
    void *lib = dlopen("/usr/local/opt/openssl@3/lib/libcrypto.3.dylib", RTLD_NOW);
    void *base = dlsym(lib, "sha256_block_data_order");
    block_fn avx2 = (block_fn)((char*)base + (0x249a40 - 0x246740));
    block_fn avx  = (block_fn)((char*)base + (0x248b40 - 0x246740));
    block_fn ssse3= (block_fn)((char*)base + (0x247c80 - 0x246740));
    block_fn def  = (block_fn)base;

    size_t len = 20000u*1024u;
    uint8_t *data = aligned_alloc(64, len);
    memset(data, 0x3c, len);
    uint8_t ref[32], o[32];
    SHA256(data, len, ref);
    sha256_via(avx2, data, len, o);
    printf("avx2 match %d\n", memcmp(ref,o,32)==0);
    sha256_via(avx, data, len, o);
    printf("avx match %d\n", memcmp(ref,o,32)==0);
    sha256_via(ssse3, data, len, o);
    printf("ssse3 match %d\n", memcmp(ref,o,32)==0);
    sha256_via(def, data, len, o);
    printf("default match %d\n", memcmp(ref,o,32)==0);

    int N=5;
    struct {const char *n; block_fn f;} fs[] = {{"avx2",avx2},{"avx",avx},{"ssse3",ssse3},{"default",def}};
    for (int k=0;k<4;k++) {
        double t0=now();
        for(int i=0;i<N;i++) sha256_via(fs[k].f, data, len, o);
        double t1=now();
        printf("%-8s %.4fs  %.1f MB/s\n", fs[k].n, (t1-t0)/N, (len*(double)N/1e6)/(t1-t0));
    }
    double t0=now();
    for(int i=0;i<N;i++) SHA256(data, len, o);
    double t1=now();
    printf("%-8s %.4fs  %.1f MB/s\n", "SHA256", (t1-t0)/N, (len*(double)N/1e6)/(t1-t0));
    free(data);
    return 0;
}
EOF
