    for(int i=0;i<N;i++) SHA256(data,len,ref);
    double t1=now();
    printf("SHA256 %.4fs %.1f MB/s\n",(t1-t0)/N,(len/((t1-t0)/N))/1e6);

    for (int nth=2; nth<=6; nth++){
        pthread_t th[8]; job_t jobs[8];
        size_t blocks=len/64;
        size_t per=blocks/nth;
        t0=now();
        for(int r=0;r<N;r++){
            for(int i=0;i<nth;i++){
                size_t b0=i*per;
                size_t b1=(i==nth-1)?blocks:(i+1)*per;
                jobs[i].data=data+b0*64;
                jobs[i].nblocks=b1-b0;
                pthread_create(&th[i],NULL,worker,&jobs[i]);
            }
            for(int i=0;i<nth;i++) pthread_join(th[i],NULL);
