static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

static const uint32_t K[64] __attribute__((aligned(64))) = {
0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

#define RORX(r, n) __builtin_ia32_rorx_u32((r), (n))

/* Fully unrolled 8 rounds using rorx. State rotated by macros. */
#define RN(a,b,c,d,e,f,g,h,i,w) do { \
    uint32_t S1 = RORX(e,6) ^ RORX(e,11) ^ RORX(e,25); \
    uint32_t ch = (e & f) ^ ((~e) & g); \
    uint32_t t1 = h + S1 + ch + K[i] + (w)[i]; \
    uint32_t S0 = RORX(a,2) ^ RORX(a,13) ^ RORX(a,22); \
    uint32_t maj = (a & b) ^ (a & c) ^ (b & c); \
    h = t1 + S0 + maj; \
    d += t1; \
} while(0)

static void rounds_all(const uint32_t *W, size_t nblocks, uint32_t Hout[8]) {
    uint32_t a=0x6a09e667,b=0xbb67ae85,c=0x3c6ef372,d=0xa54ff53a;
    uint32_t e=0x510e527f,f=0x9b05688c,g=0x1f83d9ab,h=0x5be0cd19;
    const uint32_t *w = W;
    for (size_t blk=0; blk<nblocks; blk++, w+=64) {
        uint32_t A=a,B=b,C=c,D=d,E=e,F=f,G=g,H=h;
        #define R8(base) \
          RN(A,B,C,D,E,F,G,H,base+0,w); RN(H,A,B,C,D,E,F,G,base+1,w); \
          RN(G,H,A,B,C,D,E,F,base+2,w); RN(F,G,H,A,B,C,D,E,base+3,w); \
          RN(E,F,G,H,A,B,C,D,base+4,w); RN(D,E,F,G,H,A,B,C,base+5,w); \
          RN(C,D,E,F,G,H,A,B,base+6,w); RN(B,C,D,E,F,G,H,A,base+7,w);
        R8(0) R8(8) R8(16) R8(24) R8(32) R8(40) R8(48) R8(56)
        a+=A; b+=B; c+=C; d+=D; e+=E; f+=F; g+=G; h+=H;
    }
    Hout[0]=a;Hout[1]=b;Hout[2]=c;Hout[3]=d;Hout[4]=e;Hout[5]=f;Hout[6]=g;Hout[7]=h;
}

/* Build W with openssl-speed scalar, not timed as the goal */
static inline uint32_t rr(uint32_t x,int n){return (x>>n)|(x<<(32-n));}
static void make_W(const uint8_t *data, uint32_t *W, size_t nblocks){
    for(size_t b=0;b<nblocks;b++){
        const uint8_t *p=data+b*64;
        uint32_t *w=W+b*64;
        for(int i=0;i<16;i++) w[i]=__builtin_bswap32(*(const uint32_t*)(p+4*i));
        for(int i=16;i<64;i++){
            uint32_t x=w[i-15], y=w[i-2];
            w[i]=w[i-16]+(rr(x,7)^rr(x,18)^(x>>3))+w[i-7]+(rr(y,17)^rr(y,19)^(y>>10));
        }
    }
}

int main(){
    size_t len=20000u*1024u; len&=~63ull;
    size_t nb=len/64;
    uint8_t *data=aligned_alloc(64,len);
    uint32_t *W=aligned_alloc(64, nb*64*4);
    memset(data,0x5a,len);
    printf("building W...\n");
    make_W(data,W,nb);
    uint32_t H[8];
    rounds_all(W, nb, H); /* warmup */
    printf("state %08x\n", H[0]);
    int N=5;
    double t0=now();
    for(int i=0;i<N;i++) rounds_all(W, nb, H);
    double t1=now();
    printf("rounds_only %.4fs %.1f MB/s state %08x\n",(t1-t0)/N, (len/((t1-t0)/N))/1e6, H[0]);
    return 0;
}
EOF
