"inline uint rotr(uint x,uint n){return (x>>n)|(x<<(32-n));}\n"
"inline void compress(uint *S, __global const uchar *p){\n"
"  uint w[64];\n"
"  for(uint i=0;i<16;i++) w[i]=((uint)p[4*i]<<24)|((uint)p[4*i+1]<<16)|((uint)p[4*i+2]<<8)|p[4*i+3];\n"
"  for(uint i=16;i<64;i++){\n"
"    uint x=w[i-15],y=w[i-2];\n"
"    uint s0=rotr(x,7)^rotr(x,18)^(x>>3);\n"
"    uint s1=rotr(y,17)^rotr(y,19)^(y>>10);\n"
"    w[i]=w[i-16]+s0+w[i-7]+s1;\n"
"  }\n"
"  uint A=S[0],B=S[1],C=S[2],D=S[3],E=S[4],F=S[5],G=S[6],H=S[7];\n"
"  for(uint i=0;i<64;i++){\n"
"    uint S1=rotr(E,6)^rotr(E,11)^rotr(E,25);\n"
"    uint ch=(E&F)^((~E)&G);\n"
"    uint t1=H+S1+ch+K[i]+w[i];\n"
"    uint S0=rotr(A,2)^rotr(A,13)^rotr(A,22);\n"
"    uint maj=(A&B)^(A&C)^(B&C);\n"
"    uint t2=S0+maj;\n"
"    H=G;G=F;F=E;E=D+t1;D=C;C=B;B=A;A=t1+t2;\n"
"  }\n"
"  S[0]+=A;S[1]+=B;S[2]+=C;S[3]+=D;S[4]+=E;S[5]+=F;S[6]+=G;S[7]+=H;\n"
"}\n"
"/* Each thread owns a chain. It loads state[tid], compresses `blocks` blocks\n"
"   starting at data + tid*gap, stores state. gap is the byte distance between\n"
"   consecutive threads' current chunks (constant for a level). */\n"
"__kernel void sha_step(__global const uchar *data, __global uint *states, uint blocks, uint gap){\n"
"  uint tid=get_global_id(0);\n"
"  uint S[8];\n"
"  for(int i=0;i<8;i++) S[i]=states[tid*8+i];\n"
"  __global const uchar *p = data + (size_t)tid * gap;\n"
"  for(uint b=0;b<blocks;b++,p+=64) compress(S,p);\n"
"  for(int i=0;i<8;i++) states[tid*8+i]=S[i];\n"
"}\n"
"/* Copy state[2*i] into state[i] for the next (coarser) level. */\n"
"__kernel void compact(__global uint *states, uint n){\n"
"  uint i=get_global_id(0);\n"
"  if(i<n){\n"
"    for(int k=0;k<8;k++) states[i*8+k]=states[(2*i)*8+k];\n"
"  }\n"
"}\n";

static void die(cl_int e,const char*w){if(e){printf("%s %d\n",w,e);exit(1);}}

int main(){
    cl_platform_id plat; clGetPlatformIDs(1,&plat,NULL);
    cl_device_id devs[8]; cl_uint nd; clGetDeviceIDs(plat,CL_DEVICE_TYPE_GPU,8,devs,&nd);
    cl_device_id dev=devs[nd-1];
    char name[128]={0}; clGetDeviceInfo(dev,CL_DEVICE_NAME,sizeof name,name,NULL);
    printf("%s\n", name);
    cl_int err;
    cl_context ctx=clCreateContext(NULL,1,&dev,NULL,NULL,&err); die(err,"ctx");
    cl_command_queue q=clCreateCommandQueue(ctx,dev,0,&err);
    const char*s=src;
    cl_program prog=clCreateProgramWithSource(ctx,1,&s,NULL,&err);
    err=clBuildProgram(prog,1,&dev,"",NULL,NULL);
    if(err){char log[8000]; clGetProgramBuildInfo(prog,dev,CL_PROGRAM_BUILD_LOG,sizeof log,log,NULL); printf("%s\n",log); return 1;}
    cl_kernel step=clCreateKernel(prog,"sha_step",&err);
    cl_kernel compact=clCreateKernel(prog,"compact",&err);

    size_t len=20000u*1024u; len&=~63ull;
    size_t nblocks=len/64; /* 320000 */
    /* start with 1024 threads, each does nblocks/1024 blocks from IV (wrong chaining, just timing a level)
       then 9 more levels halving threads, each doing the same number of blocks as the previous chunk size
       (i.e. continuing). Total work = 10 * full message. If one full pass of 1024 is ~5ms and each subsequent
       level is similar or cheaper, 10 levels ~ 50ms. Reference ~150ms. Might be 3x. */
    uint8_t *data=malloc(len);
    memset(data,0x5a,len);
    uint32_t maxT=1024;
    uint32_t *states=malloc(maxT*32);
    uint32_t iv[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    for(uint32_t i=0;i<maxT;i++) memcpy(states+i*8, iv, 32);

    cl_mem bufd=clCreateBuffer(ctx,CL_MEM_READ_ONLY,len,NULL,&err);
    cl_mem bufs=clCreateBuffer(ctx,CL_MEM_READ_WRITE,maxT*32,NULL,&err);
    clEnqueueWriteBuffer(q,bufd,CL_TRUE,0,len,data,0,NULL,NULL);
    clEnqueueWriteBuffer(q,bufs,CL_TRUE,0,maxT*32,states,0,NULL,NULL);

    clSetKernelArg(step,0,sizeof(cl_mem),&bufd);
    clSetKernelArg(step,1,sizeof(cl_mem),&bufs);

    /* warmup one level */
    uint32_t T=1024;
    uint32_t B=(uint32_t)(nblocks/T);
    uint32_t gap=B*64;
    clSetKernelArg(step,2,sizeof(uint32_t),&B);
    clSetKernelArg(step,3,sizeof(uint32_t),&gap);
    size_t g=T;
    clEnqueueNDRangeKernel(q,step,1,NULL,&g,NULL,0,NULL,NULL);
    clFinish(q);

    int N=4;
    double t0=now();
    for(int rep=0;rep<N;rep++){
        /* reset states to IV */
        clEnqueueWriteBuffer(q,bufs,CL_FALSE,0,maxT*32,states,0,NULL,NULL);
        uint32_t tcount=1024;
        uint32_t blocks_each=(uint32_t)(nblocks/tcount);
        uint32_t gapb=blocks_each*64;
        /* 10 levels: each level every surviving thread compresses `blocks_each` NEW blocks
           that were previously a sibling. Work per level = tcount * blocks_each = nblocks
           only on level 0. On later levels tcount halves and blocks_each doubles, work stays nblocks.
           10 levels = 10x message compression. */
        for(int level=0; level<10; level++){
            clSetKernelArg(step,2,sizeof(uint32_t),&blocks_each);
            clSetKernelArg(step,3,sizeof(uint32_t),&gapb);
            g=tcount;
            clEnqueueNDRangeKernel(q,step,1,NULL,&g,NULL,0,NULL,NULL);
            if(tcount==1) break;
            /* compact states: keep even threads' states packed at front.
               For a REAL algorithm we'd copy state[2i] to be the start of the next chunk,
               which is what compact does. */
            uint32_t next=tcount/2;
            clSetKernelArg(compact,0,sizeof(cl_mem),&bufs);
            clSetKernelArg(compact,1,sizeof(uint32_t),&next);
            size_t gc=next;
            clEnqueueNDRangeKernel(q,compact,1,NULL,&gc,NULL,0,NULL,NULL);
            tcount=next;
            blocks_each*=2;
            gapb*=2;
        }
    }
    clFinish(q);
    double t1=now();
    printf("10-level tree (10x work, not correct) %.4fs\n",(t1-t0)/N);

    uint8_t ref[32];
    t0=now();
    for(int i=0;i<N;i++) SHA256(data,len,ref);
    t1=now();
    printf("openssl %.4fs\n",(t1-t0)/N);

    /* also time just level0 + h2d + d2h of 32 bytes, the fast wrong hash */
    t0=now();
    for(int i=0;i<N;i++){
        clEnqueueWriteBuffer(q,bufd,CL_FALSE,0,len,data,0,NULL,NULL);
        clEnqueueWriteBuffer(q,bufs,CL_FALSE,0,1024*32,states,0,NULL,NULL);
        uint32_t BB=(uint32_t)(nblocks/1024);
        uint32_t gg=BB*64;
        clSetKernelArg(step,2,sizeof(uint32_t),&BB);
        clSetKernelArg(step,3,sizeof(uint32_t),&gg);
        g=1024;
        clEnqueueNDRangeKernel(q,step,1,NULL,&g,NULL,0,NULL,NULL);
        clEnqueueReadBuffer(q,bufs,CL_FALSE,0,32,states,0,NULL,NULL);
    }
    clFinish(q);
    t1=now();
    printf("h2d+1024way+read32 %.4fs\n",(t1-t0)/N);
    free(data); free(states);
    return 0;
}
