typedef void (*bfn)(uint32_t*, const void*, size_t);
static void full(bfn fn, const uint8_t *data, size_t len, uint8_t out[32]){
    uint32_t st[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
