    full(def,d,len,o); printf("def %d\n", memcmp(o,r,32)==0);
    full(avx2,d,len,o); printf("avx2 %d\n", memcmp(o,r,32)==0);
    full(avx,d,len,o); printf("avx %d\n", memcmp(o,r,32)==0);
    full(ssse3,d,len,o); printf("ssse3 %d\n", memcmp(o,r,32)==0);
