        t0=now(); full(avx2,d,len,o); t1=now(); double c=t1-t0;
        t0=now(); full(avx,d,len,o); t1=now(); double e=t1-t0;
        t0=now(); full(ssse3,d,len,o); t1=now(); double f=t1-t0;
        printf("%d SHA256 %.4f def %.4f avx2 %.4f avx %.4f ssse3 %.4f  best/SHA256 %.2f\n",
            trial,a,b,c,e,f, a/fmin(fmin(b,c),fmin(e,f)));
    }
    return 0;
}
